list-view-config.query-select:
PREFIX bibo: <http://purl.org/ontology/bibo/> PREFIX vivo: <http://vivoweb.org/ontology/core#> PREFIX obo: <http://purl.obolibrary.org/obo/> PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> PREFIX vitro: <http://vitro.mannlib.cornell.edu/ns/vitro/0.7#> PREFIX uncw: <https://scholars.uncw.edu/ontology/>
SELECT DISTINCT ?subclass ?role ?roleLabel ?event ?eventName ?eventLabel ?work ?workLabel ?venue ?venueLabel ?organizer ?dateTimeStart ?dateTimeEnd
WHERE { ?subject ?property ?role . ?role a uncw:PerformerRole .
OPTIONAL { ?subject ?property ?role . ?role a uncw:PerformerRole . ?role rdfs:label ?roleLabel . } OPTIONAL { ?subject ?property ?role . ?role a uncw:PerformerRole . ?role obo:BFO_0000054 ?event . LET (?eventName := REPLACE(STR(?event),"^.*(#)(.*)$", "$2")) OPTIONAL { ?event rdfs:label ?eventLabel . } } OPTIONAL { ?subject ?property ?role . ?role a uncw:PerformerRole . ?role obo:BFO_0000054 ?event . ?event bibo:presents ?work . ?work rdfs:label ?workLabel . } OPTIONAL { ?subject ?property ?role . ?role a uncw:PerformerRole . ?role obo:BFO_0000054 ?event . ?event obo:BFO_0000050 ?venue . ?venue a bibo:Conference . OPTIONAL { ?venue rdfs:label ?venueLabel . } OPTIONAL { ?venue bibo:organizer ?organizer . } }
OPTIONAL { ?subject ?property ?role . ?role a uncw:PerformerRole . ?role obo:BFO_0000054 ?event . ?event vitro:mostSpecificType ?subclass . }
OPTIONAL { ?subject ?property ?role . ?role a uncw:PerformerRole . ?role vivo:dateTimeInterval ?dateTimeInterval . ?dateTimeInterval vivo:start ?dateTimeStartValue . ?dateTimeStartValue vivo:dateTime ?dateTimeStart . } OPTIONAL { ?subject ?property ?role . ?role a uncw:PerformerRole . ?role vivo:dateTimeInterval ?dateTimeInterval . ?dateTimeInterval vivo:end ?dateTimeEndValue . ?dateTimeEndValue vivo:dateTime ?dateTimeEnd . }
FILTER ( bound(?event) )
} ORDER BY ?subclass DESC(?dateTimeStart) ?eventLabel ?eventName
